1	"use client";
2	
3	// Rahmen des Portals: Seitenleiste (Desktop) bzw. Drawer (mobil), Kopfzeile mit
4	// Brotkrumen, Benachrichtigungszentrale (Glocke) und Benutzer-Menü. Navigation je Rolle.
5	
6	import Link from "next/link";
7	import { usePathname, useRouter } from "next/navigation";
8	import { useEffect, useRef, useState } from "react";
9	import {
10	  Bell, Building2, ChevronDown, ClipboardList, FileText, FolderKanban, Gauge, Handshake, Inbox, LandPlot, LayoutDashboard,
11	  ListTodo, LogOut, Mail, Menu, MessagesSquare, Search, ShieldCheck, TrendingUp, UserRound, Users, X, ExternalLink, Coins,
12	} from "lucide-react";
13	import Glocke from "./Glocke";
14	import Logo from "@/components/ui/Logo";
15	import { cn } from "@/components/ui/cn";
16	import useFokusFalle from "@/components/ui/useFokusFalle";
17	import { rolleLabel } from "@/lib/plattform/konstanten";
18	import { initialen } from "@/lib/plattform/format";
19	
20	function navigation(rollen) {
21	  const hat = (...r) => r.some((x) => rollen.includes(x));
22	  const admin = rollen.includes("admin");
23	  const bereiche = [
24	    {
25	      titel: "Mein Portal",
26	      eintraege: [
27	        { href: "/portal", label: "Übersicht", icon: LayoutDashboard, exakt: true },
28	        { href: "/portal/anfragen", label: "Meine Anfragen", icon: Inbox },
29	        hat("flaeche", "landwirt") && { href: "/portal/flaechen", label: "Flächen", icon: LandPlot },
30	        hat("anbieter") && { href: "/portal/projekte", label: "Meine Projekte", icon: FolderKanban },
31	        hat("investor") && { href: "/portal/boerse", label: "Projektbörse", icon: TrendingUp },
32	        { href: "/portal/nachrichten", label: "Nachrichten", icon: MessagesSquare, zaehler: "nachrichten" },
33	        { href: "/portal/benachrichtigungen", label: "Benachrichtigungen", icon: Bell, zaehler: "hinweise" },
34	        { href: "/portal/dokumente", label: "Dokumente", icon: FileText },
35	        { href: "/portal/profil", label: hat("investor") ? "Profil & Suchprofil" : "Profil", icon: UserRound },
36	      ].filter(Boolean),
37	    },
38	  ];
39	  if (admin) {
40	    bereiche.push({
41	      titel: "Backoffice",
42	      eintraege: [
43	        { href: "/portal/admin", label: "Cockpit", icon: Gauge, exakt: true },
44	        { href: "/portal/admin/aufgaben", label: "Aufgaben", icon: ListTodo, zaehler: "aufgaben" },
45	        { href: "/portal/admin/vorgaenge", label: "Vorgänge", icon: ClipboardList },
46	        { href: "/portal/admin/flaechen", label: "Flächen-Pipeline", icon: LandPlot },
47	        { href: "/portal/admin/projekte", label: "Projekt-Freigabe", icon: ShieldCheck },
48	        { href: "/portal/admin/interessen", label: "NDA & LOI", icon: Handshake },
49	        { href: "/portal/admin/deals", label: "Deals & Provisionen", icon: Coins },
50	        { href: "/portal/admin/nutzer", label: "Nutzer & Protokoll", icon: Users },
51	        { href: "/portal/admin/postausgang", label: "E-Mail-Postausgang", icon: Mail },
52	      ],
53	    });
54	  }
55	  return bereiche;
56	}
57	
58	const LABELS = {
59	  portal: "Portal",
60	  anfragen: "Anfragen",
61	  flaechen: "Flächen",
62	  projekte: "Projekte",
63	  boerse: "Projektbörse",
64	  nachrichten: "Nachrichten",
65	  dokumente: "Dokumente",
66	  profil: "Profil",
67	  admin: "Backoffice",
68	  vorgaenge: "Vorgänge",
69	  interessen: "NDA & LOI",
70	  deals: "Deals & Provisionen",
71	  nutzer: "Nutzer",
72	  neu: "Neu",
73	  benachrichtigungen: "Benachrichtigungen",
74	  aufgaben: "Aufgaben",
75	  postausgang: "Postausgang",
76	  vergleich: "Vergleich",
77	};
78	
79	function brotkrumen(pfad) {
80	  const teile = pfad.split("/").filter(Boolean);
81	  return teile.map((t, i) => ({ href: "/" + teile.slice(0, i + 1).join("/"), label: LABELS[t] || decodeURIComponent(t) }));
82	}
83	
84	function aktiv(pfad, e) {
85	  return e.exakt ? pfad === e.href : pfad === e.href || pfad.startsWith(e.href + "/");
86	}
87	
88	export default function PortalRahmen({ nutzer, ungelesen = 0, hinweise = { eintraege: [], ungelesen: 0 }, aufgabenFaellig = 0, demo = false, children }) {
89	  const pfad = usePathname() || "/portal";
90	  const router = useRouter();
91	  const [offen, setOffen] = useState(false);
92	  const [menue, setMenue] = useState(false);
93	  const drawerRef = useRef(null);
94	  const menueRef = useRef(null);
95	  const bereiche = navigation(nutzer.rollen || []);
96	  const zaehler = { nachrichten: ungelesen, hinweise: hinweise?.ungelesen || 0, aufgaben: aufgabenFaellig };
97	
98	  useFokusFalle(offen, drawerRef, { beiEscape: () => setOffen(false) });
99	
100	  useEffect(() => {
101	    setOffen(false);
102	    setMenue(false);
103	  }, [pfad]);
104	
105	  useEffect(() => {
106	    if (!menue) return undefined;
107	    const klick = (e) => !menueRef.current?.contains(e.target) && setMenue(false);
108	    const taste = (e) => e.key === "Escape" && setMenue(false);
109	    document.addEventListener("mousedown", klick);
110	    document.addEventListener("keydown", taste);
111	    return () => {
112	      document.removeEventListener("mousedown", klick);
113	      document.removeEventListener("keydown", taste);
114	    };
115	  }, [menue]);
116	
117	  async function abmelden() {
118	    await fetch("/api/auth/logout", { method: "POST", headers: { "Content-Type": "application/json" }, body: "{}" }).catch(() => {});
119	    router.replace("/login?hinweis=abgemeldet");
120	    router.refresh();
121	  }
122	
123	  const krumen = brotkrumen(pfad);
124	  const name = [nutzer.vorname, nutzer.nachname].filter(Boolean).join(" ");
125	
126	  const nav = (
127	    <nav aria-label="Portal" className="flex-1 space-y-7 overflow-y-auto px-3 py-6">
128	      {bereiche.map((b) => (
129	        <div key={b.titel}>
130	          <p className="px-3 text-[11px] font-semibold uppercase tracking-[0.16em] text-white/40">{b.titel}</p>
131	          <ul className="mt-2 space-y-0.5">
132	            {b.eintraege.map((e) => {
133	              const ist = aktiv(pfad, e);
134	              const Icon = e.icon;
135	              return (
136	                <li key={e.href}>
137	                  <Link
138	                    href={e.href}
139	                    aria-current={ist ? "page" : undefined}
140	                    className={cn(
141	                      "group flex items-center gap-3 rounded-xl px-3 py-2.5 text-[14.5px] font-medium transition-colors",
142	                      ist ? "bg-white/[0.09] text-white" : "text-white/70 hover:bg-white/[0.05] hover:text-white"
143	                    )}
144	                  >
145	                    <Icon aria-hidden="true" className={cn("h-[18px] w-[18px] shrink-0", ist ? "text-ov-300" : "text-white/45 group-hover:text-white/80")} />
146	                    <span className="min-w-0 flex-1 truncate">{e.label}</span>
147	                    {e.zaehler && zaehler[e.zaehler] > 0 && (
148	                      <span className={cn("ov-num rounded-full px-2 py-0.5 text-[11.5px] font-bold", e.zaehler === "aufgaben" ? "bg-sun-400 text-navy-950" : "bg-ov-500 text-white")}>
149	                        {zaehler[e.zaehler]}
150	                        <span className="sr-only">{e.zaehler === "aufgaben" ? " fällig" : " ungelesen"}</span>
151	                      </span>
152	                    )}
153	                  </Link>
154	                </li>
155	              );
156	            })}
157	          </ul>
158	        </div>
159	      ))}
160	    </nav>
161	  );
162	
163	  const seitenleiste = (
164	    <>
165	      <div className="flex h-[72px] items-center px-6">
166	        <Link href="/portal" className="h-7 lg:h-9" aria-label="Portal-Übersicht">
167	          <Logo tone="dark" unterzeile={false} />
168	        </Link>
169	      </div>
170	      {demo && (
171	        <p className="mx-6 rounded-xl bg-sun-400/15 px-3 py-2 text-[12px] leading-snug text-sun-300 ring-1 ring-inset ring-sun-400/30">
172	          Demo-Modus: Alle Daten sind fiktiv.
173	        </p>
174	      )}
175	      {nav}
176	      <div className="border-t border-white/10 p-3">
177	        <Link href="/" className="flex items-center gap-3 rounded-xl px-3 py-2.5 text-[14px] text-white/60 hover:bg-white/[0.05] hover:text-white">
178	          <ExternalLink aria-hidden="true" className="h-4 w-4" /> Zur Website
179	        </Link>
180	        <button type="button" onClick={abmelden} className="flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-[14px] text-white/60 hover:bg-white/[0.05] hover:text-white">
181	          <LogOut aria-hidden="true" className="h-4 w-4" /> Abmelden
182	        </button>
183	      </div>
184	    </>
185	  );
186	
187	  return (
188	    <div className="min-h-dvh bg-sand-50">
189	      <a href="#portal-inhalt" className="sr-only focus:not-sr-only focus:fixed focus:left-4 focus:top-4 focus:z-[100] focus:rounded-full focus:bg-white focus:px-4 focus:py-2 focus:text-ink-900 focus:shadow-lg">
190	        Zum Inhalt springen
191	      </a>
192	
193	      {/* Seitenleiste Desktop */}
194	      <aside className="ov-noise fixed inset-y-0 left-0 z-30 hidden w-[272px] flex-col bg-navy-950 lg:flex">{seitenleiste}</aside>
195	
196	      {/* Drawer mobil */}
197	      <div className={cn("fixed inset-0 z-50 lg:hidden", offen ? "" : "pointer-events-none")} aria-hidden={!offen}>
198	        <div className={cn("absolute inset-0 bg-navy-950/60 backdrop-blur-sm transition-opacity", offen ? "opacity-100" : "opacity-0")} onClick={() => setOffen(false)} />
199	        <div
200	          ref={drawerRef}
201	          role="dialog"
202	          aria-modal="true"
203	          aria-label="Portal-Navigation"
204	          inert={!offen ? true : undefined}
205	          className={cn("ov-noise absolute inset-y-0 left-0 flex w-[86%] max-w-[320px] flex-col bg-navy-950 shadow-2xl transition-transform duration-300", offen ? "translate-x-0" : "-translate-x-full")}
206	        >
207	          <button type="button" onClick={() => setOffen(false)} className="absolute right-3 top-4 flex h-10 w-10 items-center justify-center rounded-full text-white/70 hover:bg-white/10 hover:text-white" aria-label="Navigation schließen">
208	            <X aria-hidden="true" className="h-5 w-5" />
209	          </button>
210	          {seitenleiste}
211	        </div>
212	      </div>
213	
214	      <div className="lg:pl-[272px]">
215	        {/* Kopfzeile */}
216	        <header className="sticky top-0 z-20 border-b border-ink-200/70 bg-white/85 backdrop-blur">
217	          <div className="flex h-16 items-center gap-3 px-4 md:px-8">
218	            <button type="button" onClick={() => setOffen(true)} className="-ml-1 flex h-10 w-10 items-center justify-center rounded-full text-ink-700 hover:bg-ink-100 lg:hidden" aria-label="Navigation öffnen" aria-expanded={offen}>
219	              <Menu aria-hidden="true" className="h-5 w-5" />
220	            </button>
221	            <Link href="/portal" className="h-7 shrink-0 lg:hidden" aria-label="Portal-Übersicht">
222	              <Logo unterzeile={false} />
223	            </Link>
224	            <nav aria-label="Brotkrumen" className="hidden min-w-0 flex-1 md:block">
225	              <ol className="flex min-w-0 items-center gap-1.5 text-[13.5px]">
226	                {krumen.map((k, i) => (
227	                  <li key={k.href} className="flex min-w-0 items-center gap-1.5">
228	                    {i > 0 && <span aria-hidden="true" className="text-ink-300">/</span>}
229	                    {i === krumen.length - 1 ? (
230	                      <span aria-current="page" className="truncate font-semibold text-ink-900">{k.label}</span>
231	                    ) : (
232	                      <Link href={k.href} className="truncate text-ink-500 hover:text-ov-700">{k.label}</Link>
233	                    )}
234	                  </li>
235	                ))}
236	              </ol>
237	            </nav>
238	            <div className="ml-auto flex items-center gap-1.5">
239	              {nutzer.rollen?.includes("investor") && (
240	                <Link href="/portal/boerse" className="hidden h-10 items-center gap-2 rounded-full px-3 text-[13.5px] font-medium text-ink-600 hover:bg-ink-100 sm:flex">
241	                  <Search aria-hidden="true" className="h-4 w-4" /> Projekte finden
242	                </Link>
243	              )}
244	              <Link href="/portal/nachrichten" className="relative hidden h-10 w-10 items-center justify-center rounded-full text-ink-700 hover:bg-ink-100 sm:flex" aria-label={ungelesen ? `Nachrichten, ${ungelesen} ungelesen` : "Nachrichten"}>
245	                <MessagesSquare aria-hidden="true" className="h-5 w-5" />
246	                {ungelesen > 0 && <span aria-hidden="true" className="absolute right-2 top-2 h-2.5 w-2.5 rounded-full bg-ov-500 ring-2 ring-white" />}
247	              </Link>
248	              <Glocke start={hinweise} />
249	              <div className="relative" ref={menueRef}>
250	                <button
251	                  type="button"
252	                  onClick={() => setMenue((m) => !m)}
253	                  aria-expanded={menue}
254	                  aria-haspopup="menu"
255	                  className="flex items-center gap-2 rounded-full py-1 pl-1 pr-2 hover:bg-ink-100"
256	                >
257	                  <span className="flex h-8 w-8 items-center justify-center rounded-full bg-navy-700 text-[12.5px] font-bold text-white">{initialen(nutzer)}</span>
258	                  <span className="hidden max-w-[160px] truncate text-[14px] font-semibold text-ink-800 sm:block">{name}</span>
259	                  <ChevronDown aria-hidden="true" className="h-4 w-4 text-ink-500" />
260	                </button>
261	                {menue && (
262	                  <div role="menu" className="absolute right-0 top-12 w-64 overflow-hidden rounded-2xl bg-white p-1.5 shadow-[0_20px_50px_-20px_rgba(3,18,43,0.45)] ring-1 ring-ink-200">
263	                    <div className="px-3 py-2.5">
264	                      <p className="truncate text-[14px] font-semibold text-ink-900">{name}</p>
265	                      <p className="truncate text-[12.5px] text-ink-500">{nutzer.email}</p>
266	                      <p className="mt-2 flex flex-wrap gap-1">
267	                        {(nutzer.rollen || []).map((r) => (
268	                          <span key={r} className="rounded-full bg-ink-100 px-2 py-0.5 text-[11px] font-semibold text-ink-600">{rolleLabel(r)}</span>
269	                        ))}
270	                      </p>
271	                    </div>
272	                    <div className="my-1 h-px bg-ink-100" />
273	                    <Link role="menuitem" href="/portal/profil" className="flex items-center gap-2.5 rounded-xl px-3 py-2 text-[14px] text-ink-700 hover:bg-ink-50">
274	                      <UserRound aria-hidden="true" className="h-4 w-4" /> Profil & Passwort
275	                    </Link>
276	                    <Link role="menuitem" href="/" className="flex items-center gap-2.5 rounded-xl px-3 py-2 text-[14px] text-ink-700 hover:bg-ink-50">
277	                      <Building2 aria-hidden="true" className="h-4 w-4" /> Zur Website
278	                    </Link>
279	                    <button role="menuitem" type="button" onClick={abmelden} className="flex w-full items-center gap-2.5 rounded-xl px-3 py-2 text-left text-[14px] text-ink-700 hover:bg-ink-50">
280	                      <LogOut aria-hidden="true" className="h-4 w-4" /> Abmelden
281	                    </button>
282	                  </div>
283	                )}
284	              </div>
285	            </div>
286	          </div>
287	        </header>
288	
289	        <div id="portal-inhalt" tabIndex={-1} className="mx-auto w-full max-w-[1320px] px-4 py-6 outline-none md:px-8 md:py-10">
290	          {children}
291	        </div>
292	      </div>
293	    </div>
294	  );
295	}
