42	/** Erlaubte Hosts für den Origin-Abgleich */
43	function erlaubteHosts(request) {
44	  const hosts = new Set();
45	  const h = request.headers.get("x-forwarded-host") || request.headers.get("host");
46	  if (h) hosts.add(h.split(",")[0].trim().toLowerCase());
47	  hosts.add(hostVon(SITE.url));
48	  for (const o of String(process.env.PLATTFORM_ORIGINS || "").split(",")) if (o.trim()) hosts.add(hostVon(o.trim()));
