60	/** JSON-Body lesen (max. Bytes), muss ein Objekt sein */
61	export async function jsonLesen(request, maxBytes = 64 * 1024) {
62	  const typ = request.headers.get("content-type") || "";
63	  if (!typ.toLowerCase().startsWith("application/json")) throw new PlattformFehler(415, "Erwartet wird JSON.");
64	  const laenge = Number(request.headers.get("content-length") || 0);
65	  if (laenge > maxBytes) throw new PlattformFehler(413, "Anfrage zu groß.");
66	  const text = await request.text();
67	  if (text.length > maxBytes) throw new PlattformFehler(413, "Anfrage zu groß.");
68	  let daten;
69	  try {
70	    daten = text ? JSON.parse(text) : {};
71	  } catch {
72	    throw new PlattformFehler(400, "Ungültiges JSON.");
73	  }
74	  if (!daten || typeof daten !== "object" || Array.isArray(daten)) throw new PlattformFehler(400, "Ungültige Daten.");
