import re
import unicodedata

import frappe

from oekoinvest_app.plattform import validierung as v
from oekoinvest_app.plattform.kern import als_json, aus_json, hat_rolle, ist_admin, jetzt_iso, nutzer, protokoll

SUCHE_MIN = 2
