		}
		for x in als(vorgang.liste, alle=admin)
	])
	quellen.append([
		{
			"art": "nachricht", "id": f"{t.get('bezugArt')}:{t.get('bezugId')}", "titel": t.get("titel") or "Unterhaltung",
