      if (!map.has(e.gruppe)) map.set(e.gruppe, []);
      map.get(e.gruppe).push(e);
    }
    return GRUPPEN_REIHENFOLGE.filter((g) => map.has(g)).map((g) => ({ id: g, titel: SUCH_GRUPPEN[g] || g, eintraege: map.get(g) }));
  }, [q, treffer, zuletzt, rollen]);

