  const ausfuehren = useCallback(
    (e, { neuerTab = false } = {}) => {
      if (!e) return;
      if (e.aktion) {
        setOffen(false);
        beiAktion?.(e.aktion);
        return;
      }
      if (!e.href) return;
      merken(e);
      if (neuerTab) {
        window.open(e.href, "_blank", "noopener");
        return;
      }
      setOffen(false);
      if (e.href === "/") window.location.assign("/");
      else router.push(e.href);
    },
    [beiAktion, merken, router, setOffen]
