// node ux_shot.mjs <email> <breite> <name> <pfad> [aktion] [voll=1]
// aktion: palette:<text> | kuerzel | tab | none
import { chromium } from "playwright";
import { fileURLToPath } from "node:url";
const [email, breite = "1440", name = "ux", pfad = "/portal", aktion = "none", voll = "1"] = process.argv.slice(2);
const B = "http://localhost:3100";
const b = await chromium.launch();
const ctx = await b.newContext({ viewport: { width: +breite, height: +breite < 600 ? 844 : 900 } });
if (email !== "-") {
  const r = await ctx.request.post(B + "/api/auth/login", { data: { email, passwort: "Demo-2026!" }, headers: { Origin: B } });
  if (r.status() !== 200) console.log("login", r.status());
}
const p = await ctx.newPage();
const fehler = [];
p.on("pageerror", (e) => fehler.push("PAGEERROR " + e.message));
p.on("console", (m) => m.type() === "error" && fehler.push("CONSOLE " + m.text().slice(0, 300)));
const res = await p.goto(B + pfad, { waitUntil: "networkidle", timeout: 180000 });
await p.waitForTimeout(800);
if (aktion.startsWith("palette")) {
  await p.keyboard.press("Control+k");
  await p.waitForTimeout(300);
  const t = aktion.split(":")[1];
  if (t) { await p.keyboard.type(t, { delay: 40 }); await p.waitForTimeout(1500); }
  await p.keyboard.press("ArrowDown");
  await p.waitForTimeout(200);
} else if (aktion === "kuerzel") {
  await p.keyboard.press("Shift+?");
  await p.waitForTimeout(400);
} else if (aktion.startsWith("klick:")) {
  await p.getByText(aktion.slice(6), { exact: false }).first().click();
  await p.waitForTimeout(1200);
}
const breiteDoc = await p.evaluate(() => document.documentElement.scrollWidth);
const datei = `${name}_${breite}.png`;
await p.screenshot({ path: fileURLToPath(new URL("./shots/" + datei, import.meta.url)), fullPage: voll === "1" });
console.log(res.status(), p.url().replace(B, ""), datei, breiteDoc > +breite ? `UEBERLAUF ${breiteDoc}` : "", fehler.length ? "\n" + fehler.join("\n") : "");
await b.close();
EOF
