  const n = await portalNutzer();
  const vorgaenge = await backend().vorgaenge(n);

  return (
    <div>
      <SeitenKopf
        eyebrow="Anfragen"
        titel="Meine Anfragen"
        text="Alle Anfragen, die Sie über die Website gestellt haben – mit aktuellem Status, Verlauf und Nachrichten."
