        </p>
      )}
      {vorgaenge.length ? (
        <ul className="grid gap-4 lg:grid-cols-2">
          {vorgaenge.map((v) => (
            <li key={v.id}>
              <Karte innen="p-5 md:p-6" className="relative h-full transition-shadow hover:ring-ov-200">
                <div className="flex flex-wrap items-start justify-between gap-3">
