                <p className="mb-4 mt-2 text-[14px] leading-relaxed text-ink-600">{v.letzterKommentar || statusInfo("vorgang", v.status).text}</p>
                <Stepper art="vorgang" status={v.status} kompakt />
              </Karte>
            </li>
          ))}
        </ul>
