        <Leer icon={Inbox} titel="Noch keine Anfragen" text="Sobald Sie über die Website eine Anfrage stellen, sehen Sie hier den Status." aktion={<Button href="/flaechencheck" size="sm" pfeil>Fläche prüfen lassen</Button>} />
      )}
    </div>
  );
}
