        { id: "stand", label: "Letzter Stand", sortierbar: false, standard: true, wert: (v) => v.letzterKommentar || statusInfo("vorgang", v.status).text, zelle: (v) => <span className="line-clamp-2 text-[13.5px] text-ink-600">{v.letzterKommentar || statusInfo("vorgang", v.status).text}</span> },
        { id: "aktualisiert", label: "Aktualisiert", wert: (v) => v.geaendertAm, zelle: (v) => <span className="whitespace-nowrap text-ink-500">{relativ(v.geaendertAm)}</span> },
      ]}
      filter={[
        { id: "status", label: "Status", wert: (v) => v.status, optionen: Object.entries(PROZESSE.vorgang.status).map(([k, s]) => ({ wert: k, label: s.label })) },
        typen.length > 1 && { id: "typ", label: "Thema", wert: (v) => v.typ, optionen: typen.map((k) => ({ wert: k, label: VORGANG_TYPEN[k] || k })) },
      ].filter(Boolean)}
      ansichten={[{ id: "offen", label: "Nur offene", zustand: { filter: { status: Object.keys(PROZESSE.vorgang.status).filter((k) => !["abgeschlossen", "abgelehnt", "zurueckgezogen"].includes(k)) } } }]}
      auswahl={false}
      leer={
        <LeerZustand
          art="anfrage"
          titel="Noch keine Anfragen"
