import { chromium } from "playwright";
import { fileURLToPath } from "node:url";
const [email, breite, ...auftraege] = process.argv.slice(2);
const B = "http://localhost:3100";
const b = await chromium.launch();
const ctx = await b.newContext({ viewport: { width: +breite, height: +breite < 600 ? 844 : 900 } });
ctx.setDefaultTimeout(240000);
if (email !== "-") {
  const r = await ctx.request.post(B + "/api/auth/login", { data: { email, passwort: "Demo-2026!" }, headers: { Origin: B }, timeout: 240000 });
  if (r.status() !== 200) console.log("login", r.status());
}
for (const a of auftraege) {
  const [name, pfad, aktion = "none", voll = "1"] = a.split("|");
  const p = await ctx.newPage();
  const fehler = [];
  p.on("pageerror", (e) => fehler.push("PAGEERROR " + e.message));
  p.on("console", (m) => m.type() === "error" && !/Failed to load resource/.test(m.text()) && fehler.push("CONSOLE " + m.text().slice(0, 300)));
  let status = 0;
  try {
    const res = await p.goto(B + pfad, { waitUntil: "load", timeout: 240000 });
    status = res.status();
    await p.waitForLoadState("networkidle", { timeout: 60000 }).catch(() => {});
    await p.waitForTimeout(1200);
    if (aktion.startsWith("palette")) {
      await p.keyboard.press("Control+k");
      await p.waitForTimeout(400);
      const t = aktion.split(":")[1];
      if (t) {
        await p.keyboard.type(t, { delay: 40 });
        await p.waitForTimeout(700);
        await p.waitForFunction(() => !document.querySelector("[role=dialog] .animate-spin"), null, { timeout: 90000 }).catch(() => {});
      }
      await p.keyboard.press("ArrowDown");
      await p.waitForTimeout(300);
    } else if (aktion === "kuerzel") {
      await p.keyboard.press("Shift+?");
      await p.waitForTimeout(500);
    } else if (aktion.startsWith("klick:")) {
      await p.getByText(aktion.slice(6), { exact: false }).first().click();
      await p.waitForTimeout(1500);
    } else if (aktion.startsWith("tab:")) {
      for (let i = 0; i < +aktion.slice(4); i++) await p.keyboard.press("Tab");
      await p.waitForTimeout(300);
    } else if (aktion.startsWith("popover:")) {
      await p.getByRole("button", { name: new RegExp(aktion.slice(8)) }).first().click();
      await p.waitForTimeout(500);
    }
    const breiteDoc = await p.evaluate(() => document.documentElement.scrollWidth);
    await p.screenshot({ path: fileURLToPath(new URL(`./shots/${name}_${breite}.png`, import.meta.url)), fullPage: voll === "1" });
    console.log(status, p.url().replace(B, ""), `${name}_${breite}.png`, breiteDoc > +breite ? `UEBERLAUF ${breiteDoc}` : "", fehler.length ? "\n  " + fehler.join("\n  ") : "");
  } catch (e) {
    console.log("FEHLER", name, e.message.split("\n")[0]);
  }
  await p.close();
}
await b.close();
EOF
